cat > src/render.js <<'EOF'
function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedEntries = (t) => [...t.m.entries()].sort((a, b) => cmp(a[0], b[0]))

function json(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const es = sortedEntries(n)
    if (!es.length) return '{}'
    return '{\n' + es.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${json(v, ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + json(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.t === 'boolean') return n.v ? 'true' : 'false'
  return JSON.stringify(n.v)
}

export const renderJson = (root) => json(root, 0) + '\n'

export function renderKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const [k, v] of sortedEntries(n)) visit(v, path === null ? k : path + '.' + k)
    } else if (n.t === 'array') {
      n.items.forEach((v, i) => visit(v, `${path}[${i}]`))
    }
  }
  const visit = (n, path) => {
    out.push(`${path} ${n.t}`)
    walk(n, path)
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
