cat > src/parser.js <<'EOF'
export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.line = 0
  }
}
const fail = (m) => {
  throw new ParseError(m)
}

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const newTable = () => ({ t: 'table', m: new Map(), headerMade: false })

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let i = 0; i < lines.length; i++) {
    try {
      const r = parseLine(lines[i], root, cur, curPath)
      if (r) {
        cur = r.table
        curPath = r.path
      }
    } catch (e) {
      if (e instanceof ParseError) e.line = i + 1
      throw e
    }
  }
  return root
}

// Walk the dotted names (all but optionally the last) from `table`, creating tables.
function walk(table, path, names) {
  let t = table
  const p = [...path]
  for (const n of names) {
    p.push(n)
    let c = t.m.get(n)
    if (c === undefined) {
      c = newTable()
      t.m.set(n, c)
    } else if (c.t === 'array' && c.aot) {
      c = c.items[c.items.length - 1]
    } else if (c.t !== 'table') {
      fail(`${p.join('.')} is not a table`)
    }
    t = c
  }
  return { t, p }
}

function assign(table, path, names, node) {
  const { t, p } = walk(table, path, names.slice(0, -1))
  const last = names[names.length - 1]
  p.push(last)
  if (t.m.has(last)) fail(`key ${p.join('.')} is defined twice`)
  t.m.set(last, node)
}

function parseLine(line, root, cur, curPath) {
  const s = new Scanner(line)
  s.skipWs()
  const c = s.peek()
  if (c === undefined || c === '#' || c === ';') return null
  if (c === '[') return parseHeader(s, root)
  const names = s.dottedName()
  s.skipWs()
  if (s.peek() !== '=') fail('expected key = value')
  s.i++
  const base = curPath
  const node = s.value(base.concat(names))
  s.skipWs()
  if (!s.atEnd()) fail('trailing text after a value')
  assign(cur, curPath, names, node)
  return null
}

function parseHeader(s, root) {
  s.i++
  const isArr = s.peek() === '['
  if (isArr) s.i++
  s.skipWs()
  const names = s.dottedName()
  s.skipWs()
  if (s.peek() !== ']') fail('unterminated table header')
  s.i++
  if (isArr) {
    if (s.peek() !== ']') fail('unterminated table header')
    s.i++
  }
  s.skipWs()
  if (!s.atEnd()) fail('trailing text after a table header')
  const { t, p } = walk(root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  p.push(last)
  const path = p.join('.')
  const ex = t.m.get(last)
  if (isArr) {
    const el = newTable()
    el.headerMade = true
    if (ex === undefined) {
      t.m.set(last, { t: 'array', aot: true, items: [el] })
    } else if (ex.t === 'array' && ex.aot) {
      ex.items.push(el)
    } else fail(`${path} is not an array of tables`)
    return { table: el, path: p }
  }
  if (ex === undefined) {
    const nt = newTable()
    nt.headerMade = true
    t.m.set(last, nt)
    return { table: nt, path: p }
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.headerMade) fail(`table ${path} is defined twice`)
  ex.headerMade = true
  return { table: ex, path: p }
}

class Scanner {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  peek() {
    return this.s[this.i]
  }
  skipWs() {
    while (isWs(this.s[this.i])) this.i++
  }
  // end of meaningful content: end of line or a comment start
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  name() {
    const c = this.peek()
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }
  dottedName() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.skipWs()
      if (this.peek() !== '.') {
        this.i = save
        return names
      }
      this.i++
      this.skipWs()
      names.push(this.name())
    }
  }
  literal() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }
  basic() {
    let out = ''
    this.i++
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      const e = this.s[this.i + 1]
      if (e === undefined) fail('unterminated string')
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, e)) {
        out += simple[e]
        this.i += 2
      } else if (e === 'u') {
        const h = this.s.slice(this.i + 2, this.i + 6)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 6
      } else {
        const cp = String.fromCodePoint(this.s.codePointAt(this.i + 1))
        fail(`invalid escape \\${cp}`)
      }
    }
  }
  value(path) {
    this.skipWs()
    const c = this.peek()
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    for (;;) {
      const d = this.s[this.i]
      if (d === undefined || isWs(d) || d === ',' || d === ']' || d === '}' || d === ';') break
      this.i++
    }
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(w)) {
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    fail(`invalid value ${w}`)
  }
  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.skipWs()
      if (this.atEnd()) fail('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return { t: 'array', aot: false, items }
      }
      items.push(this.value(path.concat(`[${items.length}]`)))
      this.skipWs()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        return { t: 'array', aot: false, items }
      } else fail('unterminated array')
    }
  }
  inline(path) {
    this.i++
    const table = newTable()
    this.skipWs()
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dottedName()
      this.skipWs()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const node = this.value(path.concat(names))
      assign(table, path, names, node)
      this.skipWs()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return table
      } else fail('unterminated inline table')
    }
  }
}
