    if (c === "'") return this.literal()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }
  dottedName() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.skipWs()
      if (this.peek() !== '.') {
        this.i = save
        return names
      }
      this.i++
      this.skipWs()
      names.push(this.name())
    }
  }
  literal() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }
  basic() {
    let out = ''
    this.i++
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      const e = this.s[this.i + 1]
      if (e === undefined) fail('unterminated string')
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, e)) {
        out += simple[e]
        this.i += 2
