    this.t = t
  }
}
const E = (t) => new Err(t)
const ERR = E('#ERR!')
const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

// ---------- tokenizer / parser ----------
class ParseFail extends Error {}

function tokenize(s) {
  const toks = []
