    if (isOp('^')) {
      p++
      return { n: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new ParseFail()
    const t = toks[p]
    if (t.k === 'num') {
      p++
      return { n: 'num', v: t.v }
    }
    if (t.k === 'op') {
