const ERR = (t) => ({ k: 'err', v: t })
export const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const c = m[1].toUpperCase()
  const col = c.length === 1 ? c.charCodeAt(0) - 64 : 26 + (c.charCodeAt(0) - 65) * 26 + (c.charCodeAt(1) - 64)
  return { col, row }
}
export function colName(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  n -= 27
  return String.fromCharCode(65 + Math.floor(n / 26), 65 + (n % 26))
}
export const key = (a) => colName(a.col) + a.row

function tokenize(s) {
  const out = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { out.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { out.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    const two = s.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { out.push({ t: 'op', v: two }); i += 2; continue }
    if ('+-*/^()=<>:,'.includes(c)) { out.push({ t: 'op', v: c }); i++; continue }
    throw new Error('lex')
  }
  return out
}

// returns { ast, misplaced, refs: [addr...] } or null if grammar rejects
export function parse(body) {
  let toks
  try { toks = tokenize(body) } catch { return null }
  let p = 0
  const refs = []
  let misplaced = false
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Error('parse') }
  const addRef = (w) => { const a = parseAddr(w); if (a) refs.push(a); return a }

  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
