  const memo = new Map()
  const busy = new Set()
  const getCell = (a) => {
    const k = key(a)
    const c = cells.get(k)
    if (!c) return { k: 'num', v: 0 }
    if (c.lit) return c.lit
    if (memo.has(k)) return memo.get(k)
    if (busy.has(k)) return { k: 'err', v: '#CYCLE!' }
