    const v = getCell(c.a)
    let t
    if (v.k === 'num') t = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'bool') t = v.v ? 'TRUE' : 'FALSE'
    else t = v.v
    out.push(`${key(c.a)}=${t}`)
  }
}
