import { readFileSync } from 'node:fs'

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let names = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const at = `line ${i + 1}: `
    if (t[0] === 'candidates') {
      if (names !== null) fail(at + 'candidates must be declared once, before any ballot')
      if (t.length < 2) fail(at + 'expected candidates <name>...')
      names = []
      for (const n of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(n)) fail(at + `invalid candidate name ${n}`)
        if (names.includes(n)) fail(at + `candidate ${n} is declared twice`)
        names.push(n)
      }
    } else if (t[0] === 'ballot') {
      if (names === null) fail(at + 'candidates must be declared once, before any ballot')
      if (t.length < 3) fail(at + 'expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(at + 'count must be a positive integer')
      const seen = new Set()
      for (const n of t.slice(2)) {
        if (!names.includes(n)) fail(at + `unknown candidate ${n}`)
        if (seen.has(n)) fail(at + `candidate ${n} is repeated`)
        seen.add(n)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else fail(at + `unknown directive ${t[0]}`)
  }
  if (names === null) fail('no candidates')
  return { names, ballots }
}

function run(names, ballots) {
  const continuing = new Set(names)
  const history = [] // Map per round
  const out = []
  let winner = null
  for (;;) {
    const counts = new Map([...continuing].map((n) => [n, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
    }
    history.push(counts)
    let total = 0n
    for (const b of ballots) total += b.count
    const sorted = [...counts].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const row = { text: `round ${history.length}: ${sorted.map(([n, v]) => `${n}=${v}`).join(' ')} exhausted=${total - active}` }
    out.push(row)
    if (active === 0n) break
    const win = sorted.find(([, v]) => v * 2n > active)
    if (win) { winner = win[0]; break }
    let min = sorted[sorted.length - 1][1]
    let tied = sorted.filter(([, v]) => v === min).map(([n]) => n)
    for (let r = 0; tied.length > 1 && r < history.length; ) {
      const vs = tied.map((n) => history[r].get(n))
      const m = vs.reduce((a, b) => (a < b ? a : b))
      if (vs.every((v) => v === m)) { r++; continue }
      tied = tied.filter((n, k) => vs[k] === m)
      r = 0
    }
    const elim = tied.sort().pop()
    continuing.delete(elim)
    row.elim = elim
  }
  return { out, winner, rounds: history.length }
}

const mode = process.argv.length === 3 ? process.argv[2] : null
try {
  if (mode !== 'rounds' && mode !== 'tally') fail('usage: cli.js rounds|tally')
  const { names, ballots } = parse(readFileSync(0, 'utf8'))
  const r = run(names, ballots)
  let s = ''
  if (mode === 'rounds') for (const row of r.out) s += row.text + '\n' + (row.elim ? `eliminated ${row.elim}\n` : '')
  else s += `rounds ${r.rounds}\n`
  s += r.winner ? `winner ${r.winner}\n` : 'no winner\n'
  process.stdout.write(s)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
}
EOF
