cat > src/uri.js <<'EOF'
export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  let scheme = null
  const m = /^[^:/?#]+:/.exec(s)
  if (m) {
    scheme = m[0].slice(0, -1)
    s = s.slice(m[0].length)
  }
  let authority = null
  if (s.startsWith('//')) {
    const end = s.slice(2).search(/[/?#]/)
    authority = end < 0 ? s.slice(2) : s.slice(2, 2 + end)
    s = end < 0 ? '' : s.slice(2 + end)
  }
  let fragment = null
  const h = s.indexOf('#')
  if (h >= 0) {
    fragment = s.slice(h + 1)
    s = s.slice(0, h)
  }
  let query = null
  const q = s.indexOf('?')
  if (q >= 0) {
    query = s.slice(q + 1)
    s = s.slice(0, q)
  }
  return { scheme, authority, path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) {
    userinfo = a.slice(0, at)
    a = a.slice(at + 1)
  }
  let port = null
  const c = a.indexOf(':', a.lastIndexOf(']') + 1)
  // lastIndexOf returns -1 when absent, so the search starts at 0
  if (c >= 0) {
    port = a.slice(c + 1)
    a = a.slice(0, c)
  }
  return { userinfo, host: a, port }
}

function checkPct(s, name) {
  if (s !== null && /%(?![0-9A-Fa-f]{2})/.test(s)) {
    throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
}

function normPct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(path) {
  let input = path
  let out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

function check(p) {
  let ui = null
  let host = null
  if (p.authority !== null) {
    const a = splitAuthority(p.authority)
    ui = a.userinfo
    host = a.host
  }
  checkPct(p.path, 'path')
  checkPct(ui, 'userinfo')
  checkPct(host, 'host')
  checkPct(p.query, 'query')
  checkPct(p.fragment, 'fragment')
}

function serialize(p) {
  let r = ''
  if (p.scheme !== null) r += p.scheme + ':'
  if (p.authority !== null) r += '//' + p.authority
  r += p.path
  if (p.query !== null) r += '?' + p.query
  if (p.fragment !== null) r += '#' + p.fragment
  return r
}

function normalizeParsed(p) {
  check(p)
  const scheme = p.scheme === null ? null : lowerAscii(p.scheme)
  let authority = null
  if (p.authority !== null) {
    const a = splitAuthority(p.authority)
    let s = ''
    if (a.userinfo !== null) s += normPct(a.userinfo) + '@'
    s += lowerAscii(normPct(a.host))
    if (a.port !== null && a.port !== '' && a.port !== DEFAULT_PORTS[scheme]) s += ':' + a.port
    authority = s
  }
  let path = removeDots(normPct(p.path))
  if (authority !== null && path === '') path = '/'
  return {
    scheme,
    authority,
    path,
    query: p.query === null ? null : normPct(p.query),
    fragment: p.fragment === null ? null : normPct(p.fragment),
  }
}

export function normalizeRef(s) {
  return serialize(normalizeParsed(parse(s)))
}

export function resolveRef(baseStr, refStr) {
  const b = parse(baseStr)
  if (b.scheme === null) throw new UriError('the base has no scheme')
  const r = parse(refStr)
  let t
  if (r.scheme !== null) {
    t = { ...r, path: removeDots(r.path) }
  } else if (r.authority !== null) {
    t = { ...r, scheme: b.scheme, path: removeDots(r.path) }
  } else if (r.path === '') {
    t = { scheme: b.scheme, authority: b.authority, path: b.path, query: r.query !== null ? r.query : b.query, fragment: r.fragment }
  } else {
    let path
    if (r.path.startsWith('/')) path = r.path
    else if (b.authority !== null && b.path === '') path = '/' + r.path
    else {
      const i = b.path.lastIndexOf('/')
      path = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path
    }
    t = { scheme: b.scheme, authority: b.authority, path: removeDots(path), query: r.query, fragment: r.fragment }
  }
  return serialize(normalizeParsed(t))
}
