    if (PUNCT2.has(two)) { advN(2); toks.push({ kind: 'punct', text: two, line: sl, col: sc }); continue }
    if (PUNCT1.has(c)) { adv(); toks.push({ kind: 'punct', text: c, line: sl, col: sc }); continue }
