/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(text, field, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

// Bucket tokens are stored scaled by `per` so fractions stay exact.
function makeBucket(p) {
  return {
    fresh: () => ({ n: p.capacity * p.per, last: null }),
    advance(s, tick) {
      if (s.last !== null) {
        s.n += p.refill * (tick - s.last)
        const cap = p.capacity * p.per
        if (s.n > cap) s.n = cap
      }
      s.last = tick
    },
    ask: (s) => s.n >= p.per,
    record(s) { s.n -= p.per },
  }
}

function makeWindow(p) {
  return {
    fresh: () => ({ t: [] }),
    advance(s, tick) {
      const edge = tick - p.span
      s.t = s.t.filter((x) => x > edge)
    },
    ask: (s) => BigInt(s.t.length) < p.limit,
    record(s, tick) { s.t.push(tick) },
  }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let prev = null
  let lineNo = 0
  try {
    for (const raw of lines) {
      lineNo++
      const line = raw.trim()
      if (line === '' || line.startsWith('#')) continue
      const w = line.split(/\s+/)
      const d = w[0]
      if (d === 'bucket' || d === 'window') {
        const isB = d === 'bucket'
        if (w.length !== (isB ? 5 : 4)) {
          throw new Fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        }
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(w[1])) throw new Fail(`invalid policy name ${w[1]}`)
        let p
        if (isB) {
          p = { capacity: num(w[2], 'capacity', 1), refill: num(w[3], 'refill', 0), per: num(w[4], 'per', 1) }
        } else {
          p = { limit: num(w[2], 'limit', 0), span: num(w[3], 'span', 1) }
        }
        if (policies.has(w[1])) throw new Fail(`policy ${w[1]} is declared twice`)
        policies.set(w[1], { name: w[1], ...(isB ? makeBucket(p) : makeWindow(p)) })
      } else if (d === 'route') {
        if (w.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (started) throw new Fail('declarations must come before the first event')
        if (!NAME.test(w[1])) throw new Fail(`invalid route prefix ${w[1]}`)
        if (routes.has(w[1])) throw new Fail(`prefix ${w[1]} is routed twice`)
        const list = []
        for (const n of w.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(w[1], list)
      } else if (d === 'event') {
        if (w.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num(w[1], 'tick', 0)
        if (!NAME.test(w[2])) throw new Fail(`invalid key ${w[2]}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${w[1]} is before tick ${prev}`)
        prev = tick
        started = true
        events.push({ tick, tickText: w[1], key: w[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    }
  } catch (e) {
    if (e instanceof Fail) {
      process.stderr.write(`error: line ${lineNo}: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }
  return { routes, events }
}

const { routes, events } = parse(readFileSync(0, 'utf8'))
const states = new Map() // key -> Map(policy -> state)
const out = []
const stats = new Map()
let ta = 0
let td = 0

for (const ev of events) {
  let best = null
  for (const [prefix, list] of routes) {
    if (ev.key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
  }
  let denier = null
  if (best !== null) {
    const list = routes.get(best)
    let ks = states.get(ev.key)
    if (!ks) states.set(ev.key, (ks = new Map()))
    for (const p of list) {
      if (!ks.has(p)) ks.set(p, p.fresh())
      p.advance(ks.get(p), ev.tick)
    }
    for (const p of list) {
      if (!p.ask(ks.get(p))) { denier = p; break }
    }
    if (!denier) for (const p of list) p.record(ks.get(p), ev.tick)
  }
  const st = stats.get(ev.key) ?? { a: 0, d: 0 }
  stats.set(ev.key, st)
  if (denier) { st.d++; td++ } else { st.a++; ta++ }
  out.push(`${ev.tickText} ${ev.key} ${denier ? 'deny ' + denier.name : 'allow'}`)
}

if (mode === 'summary') {
  const keys = [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))
  const res = keys.map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  res.push(`total allowed=${ta} denied=${td}`)
  process.stdout.write(res.join('\n') + '\n')
} else if (out.length) {
  process.stdout.write(out.join('\n') + '\n')
}
"}

