export function diffChanges(a, b) {
  const n = a.length, m = b.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = a[i] === b[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const changes = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (bs !== i || ss !== j) changes.push({ bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && a[i] === b[j]) {
      flush(); i++; j++; bs = i; ss = j
    } else if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return changes
}

const eq = (x, y) => x.length === y.length && x.every((v, k) => v === y[k])

export function resolve(mine, base, theirs) {
  const all = [
    ...diffChanges(base, mine).map(c => ({ ...c, side: 0 })),
    ...diffChanges(base, theirs).map(c => ({ ...c, side: 1 })),
  ].sort((x, y) => x.bs - y.bs)
  const docs = [mine, theirs]
  const res = []
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) res.push({ kind: 'stable', lines: base.slice(pos, rs) })
    const baseLines = base.slice(rs, re)
    const rep = [0, 1].map(s => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseLines
      const minB = Math.min(...cs.map(c => c.bs)), maxB = Math.max(...cs.map(c => c.be))
      const st = Math.min(...cs.map(c => c.ss)) - (minB - rs)
      const en = Math.max(...cs.map(c => c.se)) + (re - maxB)
      return docs[s].slice(st, en)
    })
    const [m, t] = rep
    if (eq(m, t)) res.push({ kind: 'both', lines: m })
    else if (eq(m, baseLines)) res.push({ kind: 'theirs', lines: t })
    else if (eq(t, baseLines)) res.push({ kind: 'mine', lines: m })
    else res.push({ kind: 'conflict', mine: m, base: baseLines, theirs: t })
    pos = re
  }
  if (pos < base.length) res.push({ kind: 'stable', lines: base.slice(pos) })
  return res
}
